  function svg(name, dim) {
    const inner = HEAR_ICONS[name];
    if (inner == null) {
      if (window.console) console.warn('[ds-icons] not in library: "' + name + '"');
      return null;
    }
    dim = dim || '1em';
    return '<svg viewBox="0 0 16 16" width="' + dim + '" height="' + dim + '" fill="currentColor" class="hds-icon" aria-hidden="true" focusable="false" style="display:inline-block;vertical-align:-0.125em;flex:none">' + inner + '</svg>';
  }
  window.hdsIcon = function (name, size, cls) {
    var s = svg(name, size ? size + '' : '1em');
    if (!s) return '';
    if (cls) s = s.replace('class="hds-icon"', 'class="hds-icon ' + cls + '"');
    return s;
  };
